Object.assign(SNIP,{});PRESET_NOTES["l30"]={"Ví dụ: Địa chỉ trực tiếp": "Khóa chính là chỉ số: đếm, thêm, tra đều O(1). Chỉ dùng được khi khóa là số nguyên trong một khoảng nhỏ.", "Ví dụ: Bảng băm dò tuyến tính": "31 có h = 3 nhưng ô 3 đã có 10 nên dò sang ô 4; 4 có h = 4, ô bận nên sang ô 5; 15 có h = 1, ô 1 bận nên sang ô 2. Tìm 17 (h = 3): dò ô 3, 4, 5, 6 rồi gặp ô trống, kết luận không có.", "Ví dụ: Bảng băm dây chuyền bằng mảng": "12, 7, 22 cùng h = 2 nên nối thành một danh sách: head[2] = 3 (khóa 22) → nxt[3] = 1 (khóa 7) → nxt[1] = 0 (khóa 12) → −1. Tra 22 chỉ đi dọc danh sách ô 2, không đụng tới các khóa khác.", "Ví dụ: Khóa xấu dồn vào một ô": "Mọi khóa đều có h = 0, nên khóa thứ j phải dò qua j − 1 ô: tổng 0 + 1 + … + 6 = 21 lần dò, đúng kiểu O(n²). M = 8 là lũy thừa của 2 nên rất dễ gặp chuyện này; đổi M thành 7 (số nguyên tố) rồi chạy lại để so sánh.", "Lỗi: bảng đầy, dò mãi không dừng": "Tìm khóa không có trong bảng đã đầy: vòng dò đi vòng tròn mãi vì không còn ô trống nào để dừng. Trình mô phỏng dừng khi vượt giới hạn số bước. Bảng dò tuyến tính phải luôn còn ô trống (giữ hệ số tải dưới khoảng 0,5–0,7, đầy thì dựng lại bảng lớn hơn)."};EX_HINTS["l30"]=[["Ô bắt đầu là x % M. Thêm: dò tới khi gặp ô trống hoặc ô đã chứa đúng x (thêm trùng thì không làm gì).", "Tìm: dò từ x % M; gặp x thì có, gặp ô trống thì không có.", "M = 20011 lớn hơn gấp đôi số khóa tối đa nên bảng luôn còn nhiều ô trống, đường dò ngắn."], ["Đọc lần lượt; với mỗi x, hỏi “đã gặp x chưa?”. Lần đầu có câu trả lời “rồi” chính là đáp án. Mẹo: lưu x + 1 để số 0 nghĩa là ô trống, khỏi phải gán −1 cho 200 003 ô.", "Một vòng dò làm cả hai việc: dừng ở ô chứa x (đã gặp) hoặc ở ô trống (chưa gặp, ghi x vào đó).", "So từng cặp là O(n²)."], ["Hàm băm chuỗi: h = 0, rồi với mỗi ký tự c: h = (h * 31 + c) % M. Dùng long long cho h để h * 31 không tràn.", "Thêm phần tử i vào ô h: nxt[i] = head[h]; head[h] = i.", "Tra tên t: đi i = head[bam(t)], i = nxt[i], … tới −1; so sánh ten[i] == t."]];
/* ===================== BÀI 30 · Bảng băm hoạt động ra sao; va chạm và cách xử lý ===================== */
/* Bài 30 · Bảng băm hoạt động ra sao; va chạm và cách xử lý
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const PR30=[{label:"Ví dụ: Địa chỉ trực tiếp",input:"",code:"#include <iostream>\nusing namespace std;\n\nint dem[10];      // dem[x]: số lần x xuất hiện (0 <= x <= 9)\n\nint main() {\n    int a[8] = {3, 1, 4, 1, 5, 9, 2, 6};\n    for (int i = 0; i < 8; i++) dem[a[i]]++;\n    cout << dem[1] << \" \" << dem[7] << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a",ptr:["i"]},{type:"cells",of:"dem"}],py:{code:"dem = [0] * 10      # dem[x]: số lần x xuất hiện (0 <= x <= 9)\na = [3, 1, 4, 1, 5, 9, 2, 6]\nfor i in range(len(a)):\n    dem[a[i]] += 1\nprint(dem[1], dem[7])"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] dem = new int[10];      // dem[x]: số lần x xuất hiện (0 <= x <= 9)\n        int[] a = { 3, 1, 4, 1, 5, 9, 2, 6 };\n        for (int i = 0; i < a.Length; i++) dem[a[i]]++;\n        Console.WriteLine(dem[1] + \" \" + dem[7]);\n    }\n}"}},{label:"Ví dụ: Bảng băm dò tuyến tính",input:"",code:"#include <iostream>\nusing namespace std;\n\nconst int M = 7;\nint bang[M];        // -1: ô trống\n\nvoid them(int x) {\n    int i = x % M;\n    while (bang[i] != -1 && bang[i] != x) i = (i + 1) % M;   // ô bận: dò ô kế tiếp\n    bang[i] = x;\n}\n\nbool co(int x) {\n    int i = x % M;\n    while (bang[i] != -1) {\n        if (bang[i] == x) return true;\n        i = (i + 1) % M;\n    }\n    return false;          // gặp ô trống: x không có trong bảng\n}\n\nint main() {\n    for (int i = 0; i < M; i++) bang[i] = -1;\n    int k[5] = {10, 22, 31, 4, 15};\n    for (int j = 0; j < 5; j++) them(k[j]);\n    cout << co(31) << \" \" << co(17) << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"bang",ptr:["i"]}],py:{code:"M = 7\nbang = [-1] * M       # -1: ô trống\n\ndef them(x):\n    i = x % M\n    while bang[i] != -1 and bang[i] != x:\n        i = (i + 1) % M           # ô bận: dò ô kế tiếp\n    bang[i] = x\n\ndef co(x):\n    i = x % M\n    while bang[i] != -1:\n        if bang[i] == x:\n            return True\n        i = (i + 1) % M\n    return False                  # gặp ô trống: x không có trong bảng\n\nfor k in [10, 22, 31, 4, 15]:\n    them(k)\nprint(co(31), co(17))"},cs:{code:"using System;\n\nclass Program\n{\n    const int M = 7;\n    static int[] bang = new int[M];        // -1: ô trống\n\n    static void Them(int x)\n    {\n        int i = x % M;\n        while (bang[i] != -1 && bang[i] != x) i = (i + 1) % M;   // ô bận: dò ô kế tiếp\n        bang[i] = x;\n    }\n\n    static bool Co(int x)\n    {\n        int i = x % M;\n        while (bang[i] != -1)\n        {\n            if (bang[i] == x) return true;\n            i = (i + 1) % M;\n        }\n        return false;          // gặp ô trống: x không có trong bảng\n    }\n\n    static void Main()\n    {\n        for (int i = 0; i < M; i++) bang[i] = -1;\n        int[] k = { 10, 22, 31, 4, 15 };\n        foreach (int x in k) Them(x);\n        Console.WriteLine(Co(31) + \" \" + Co(17));\n    }\n}"}},{label:"Ví dụ: Bảng băm dây chuyền bằng mảng",input:"",code:"#include <iostream>\nusing namespace std;\n\nconst int M = 5;\nint head[M];        // head[h]: phần tử đầu của danh sách ô h (-1: rỗng)\nint khoa[100], nxt[100], n = 0;\n\nvoid them(int x) {\n    int h = x % M;\n    khoa[n] = x;\n    nxt[n] = head[h];     // gắn phần tử mới vào đầu danh sách ô h\n    head[h] = n;\n    n++;\n}\n\nbool co(int x) {\n    for (int i = head[x % M]; i != -1; i = nxt[i])\n        if (khoa[i] == x) return true;\n    return false;\n}\n\nint main() {\n    for (int h = 0; h < M; h++) head[h] = -1;\n    int k[6] = {12, 7, 3, 22, 18, 9};\n    for (int j = 0; j < 6; j++) them(k[j]);\n    cout << co(22) << \" \" << co(17) << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"head",ptr:["h"]},{type:"cells",of:"khoa",ptr:["i"]},{type:"cells",of:"nxt",ptr:["i"]}],py:{code:"M = 5\nhead = [-1] * M        # head[h]: phần tử đầu của danh sách ô h (-1: rỗng)\nkhoa = []\nnxt = []\n\ndef them(x):\n    h = x % M\n    khoa.append(x)\n    nxt.append(head[h])   # phần tử mới trỏ tới đầu cũ của danh sách ô h\n    head[h] = len(khoa) - 1\n\ndef co(x):\n    i = head[x % M]\n    while i != -1:\n        if khoa[i] == x:\n            return True\n        i = nxt[i]\n    return False\n\nfor k in [12, 7, 3, 22, 18, 9]:\n    them(k)\nprint(co(22), co(17))",viz:[{type:"cells",of:"head",ptr:["h"]},{type:"cells",of:"khoa",ptr:["i"]},{type:"cells",of:"nxt",ptr:["i"]}]},cs:{code:"using System;\n\nclass Program\n{\n    const int M = 5;\n    static int[] head = new int[M];        // head[h]: phần tử đầu của danh sách ô h (-1: rỗng)\n    static int[] khoa = new int[100], nxt = new int[100];\n    static int n = 0;\n\n    static void Them(int x)\n    {\n        int h = x % M;\n        khoa[n] = x;\n        nxt[n] = head[h];     // gắn phần tử mới vào đầu danh sách ô h\n        head[h] = n;\n        n++;\n    }\n\n    static bool Co(int x)\n    {\n        for (int i = head[x % M]; i != -1; i = nxt[i])\n            if (khoa[i] == x) return true;\n        return false;\n    }\n\n    static void Main()\n    {\n        for (int h = 0; h < M; h++) head[h] = -1;\n        int[] k = { 12, 7, 3, 22, 18, 9 };\n        foreach (int x in k) Them(x);\n        Console.WriteLine(Co(22) + \" \" + Co(17));\n    }\n}",viz:[{type:"cells",of:"head",ptr:["h"]},{type:"cells",of:"khoa",ptr:["i"]},{type:"cells",of:"nxt",ptr:["i"]}]}},{label:"Ví dụ: Khóa xấu dồn vào một ô",input:"",code:"#include <iostream>\nusing namespace std;\n\nconst int M = 8;\nint bang[M], soLanDo = 0;\n\nvoid them(int x) {\n    int i = x % M;\n    while (bang[i] != -1) { i = (i + 1) % M; soLanDo++; }\n    bang[i] = x;\n}\n\nint main() {\n    for (int i = 0; i < M; i++) bang[i] = -1;\n    for (int j = 1; j <= 7; j++) them(16 * j);    // 16, 32, 48... đều chia hết cho 8\n    cout << soLanDo << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"bang",ptr:["i"]},{type:"vars",names:["soLanDo"]}],py:{code:"M = 8\nbang = [-1] * M\nsoLanDo = 0\n\ndef them(x):\n    global soLanDo\n    i = x % M\n    while bang[i] != -1:\n        i = (i + 1) % M\n        soLanDo += 1\n    bang[i] = x\n\nfor j in range(1, 8):\n    them(16 * j)          # 16, 32, 48... đều chia hết cho 8\nprint(soLanDo)"},cs:{code:"using System;\n\nclass Program\n{\n    const int M = 8;\n    static int[] bang = new int[M];\n    static int soLanDo = 0;\n\n    static void Them(int x)\n    {\n        int i = x % M;\n        while (bang[i] != -1) { i = (i + 1) % M; soLanDo++; }\n        bang[i] = x;\n    }\n\n    static void Main()\n    {\n        for (int i = 0; i < M; i++) bang[i] = -1;\n        for (int j = 1; j <= 7; j++) Them(16 * j);    // 16, 32, 48... đều chia hết cho 8\n        Console.WriteLine(soLanDo);\n    }\n}"}},{label:"Lỗi: bảng đầy, dò mãi không dừng",input:"",code:"#include <iostream>\nusing namespace std;\n\nconst int M = 4;\nint bang[M];\n\nbool co(int x) {\n    int i = x % M;\n    while (bang[i] != -1) {          // không bao giờ gặp ô trống\n        if (bang[i] == x) return true;\n        i = (i + 1) % M;\n    }\n    return false;\n}\n\nint main() {\n    for (int i = 0; i < M; i++) bang[i] = i * 10;   // bảng đã đầy: 0 10 20 30\n    cout << co(5) << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"bang",ptr:["i"]}],py:{code:"M = 4\nbang = [0, 10, 20, 30]    # bảng đã đầy\n\ndef co(x):\n    i = x % M\n    while bang[i] != -1:     # không bao giờ gặp ô trống\n        if bang[i] == x:\n            return True\n        i = (i + 1) % M\n    return False\n\nprint(co(5))"},cs:{code:"using System;\n\nclass Program\n{\n    const int M = 4;\n    static int[] bang = new int[M];\n\n    static bool Co(int x)\n    {\n        int i = x % M;\n        while (bang[i] != -1)          // không bao giờ gặp ô trống\n        {\n            if (bang[i] == x) return true;\n            i = (i + 1) % M;\n        }\n        return false;\n    }\n\n    static void Main()\n    {\n        for (int i = 0; i < M; i++) bang[i] = i * 10;   // bảng đã đầy: 0 10 20 30\n        Console.WriteLine(Co(5));\n    }\n}"}}];
